101	DUCKDB_API string Connection::GetSubstrait(const string &query) {
102		vector<Value> params;
103		params.emplace_back(query);
104		auto result = TableFunction("get_substrait", params)->Execute();
105		auto protobuf = result->FetchRaw()->GetValue(0, 0);
106		return protobuf.GetValueUnsafe<string_t>().GetString();
107	}
