97	unique_ptr<PendingQueryResult> PreparedStatement::PendingQuery(case_insensitive_map_t<BoundParameterData> &named_values,
98	                                                               bool allow_stream_result) {
99		if (!success) {
100			auto exception = InvalidInputException("Attempting to execute an unsuccessfully prepared statement!");
101			return make_uniq<PendingQueryResult>(ErrorData(exception));
102		}
103		PendingQueryParameters parameters;
104		parameters.parameters = &named_values;
105	
106		try {
107			VerifyParameters(named_values, named_param_map);
108		} catch (const std::exception &ex) {
109			return make_uniq<PendingQueryResult>(ErrorData(ex));
110		}
111	
112		D_ASSERT(data);
113		parameters.allow_stream_result = allow_stream_result && data->properties.allow_stream_result;
114		auto result = context->PendingQuery(query, data, parameters);
115		// The result should not contain any reference to the 'vector<Value> parameters.parameters'
116		return result;
117	}
