735	unique_ptr<PendingQueryResult> ClientContext::PendingStatementInternal(ClientContextLock &lock, const string &query,
736	                                                                       unique_ptr<SQLStatement> statement,
737	                                                                       const PendingQueryParameters &parameters) {
738		// prepare the query for execution
739		auto prepared = CreatePreparedStatement(lock, query, std::move(statement), parameters.parameters,
740		                                        PreparedStatementMode::PREPARE_AND_EXECUTE);
741		idx_t parameter_count = !parameters.parameters ? 0 : parameters.parameters->size();
742		if (prepared->properties.parameter_count > 0 && parameter_count == 0) {
743			string error_message = StringUtil::Format("Expected %lld parameters, but none were supplied",
744			                                          prepared->properties.parameter_count);
745			return ErrorResult<PendingQueryResult>(InvalidInputException(error_message), query);
746		}
747		if (!prepared->properties.bound_all_parameters) {
748			return ErrorResult<PendingQueryResult>(InvalidInputException("Not all parameters were bound"), query);
749		}
750		// execute the prepared statement
751		CheckIfPreparedStatementIsExecutable(*prepared);
752		return PendingPreparedStatementInternal(lock, std::move(prepared), parameters);
753	}
