774	unique_ptr<PendingQueryResult> ClientContext::PendingStatementOrPreparedStatementInternal(
775	    ClientContextLock &lock, const string &query, unique_ptr<SQLStatement> statement,
776	    shared_ptr<PreparedStatementData> &prepared, const PendingQueryParameters &parameters) {
777	#ifdef DUCKDB_ALTERNATIVE_VERIFY
778		if (statement && statement->type != StatementType::LOGICAL_PLAN_STATEMENT) {
779			statement = statement->Copy();
780		}
781	#endif
782		// check if we are on AutoCommit. In this case we should start a transaction.
783		if (statement && config.AnyVerification()) {
784			// query verification is enabled
785			// create a copy of the statement, and use the copy
786			// this way we verify that the copy correctly copies all properties
787			auto copied_statement = statement->Copy();
788			switch (statement->type) {
789			case StatementType::SELECT_STATEMENT: {
790				// in case this is a select query, we verify the original statement
791				ErrorData error;
792				try {
793					error = VerifyQuery(lock, query, std::move(statement));
794				} catch (std::exception &ex) {
795					error = ErrorData(ex);
796				}
797				if (error.HasError()) {
798					// error in verifying query
799					return ErrorResult<PendingQueryResult>(std::move(error), query);
800				}
801				statement = std::move(copied_statement);
802				break;
803			}
804			default: {
805	#ifndef DUCKDB_ALTERNATIVE_VERIFY
806				bool reparse_statement = true;
807	#else
808				bool reparse_statement = false;
809	#endif
810				statement = std::move(copied_statement);
811				if (statement->type == StatementType::RELATION_STATEMENT) {
812					reparse_statement = false;
813				}
814				if (reparse_statement) {
815					try {
816						Parser parser(GetParserOptions());
817						ErrorData error;
818						parser.ParseQuery(statement->ToString());
819						statement = std::move(parser.statements[0]);
820					} catch (const NotImplementedException &) {
821						// ToString was not implemented, just use the copied statement
822					}
823				}
824				break;
825			}
826			}
827		}

