831	unique_ptr<PendingQueryResult> ClientContext::PendingStatementOrPreparedStatement(
832	    ClientContextLock &lock, const string &query, unique_ptr<SQLStatement> statement,
833	    shared_ptr<PreparedStatementData> &prepared, const PendingQueryParameters &parameters) {
834		unique_ptr<PendingQueryResult> pending;
835	
836		try {
837			BeginQueryInternal(lock, query);
838		} catch (std::exception &ex) {
839			ErrorData error(ex);
840			if (Exception::InvalidatesDatabase(error.Type())) {
841				// fatal exceptions invalidate the entire database
842				auto &db_instance = DatabaseInstance::GetDatabase(*this);
843				ValidChecker::Invalidate(db_instance, error.RawMessage());
844			}
845			return ErrorResult<PendingQueryResult>(std::move(error), query);
846		}
847		// start the profiler
848		auto &profiler = QueryProfiler::Get(*this);
849		profiler.StartQuery(query, IsExplainAnalyze(statement ? statement.get() : prepared->unbound_statement.get()));
850	
851		bool invalidate_query = true;
852		try {
853			if (statement) {
854				pending = PendingStatementInternal(lock, query, std::move(statement), parameters);
855			} else {
856				pending = PendingPreparedStatement(lock, query, prepared, parameters);
857			}
858		} catch (std::exception &ex) {
859			ErrorData error(ex);
860			if (!Exception::InvalidatesTransaction(error.Type())) {
861				// standard exceptions do not invalidate the current transaction
862				invalidate_query = false;
863			} else if (Exception::InvalidatesDatabase(error.Type())) {
864				// fatal exceptions invalidate the entire database
865				if (!config.query_verification_enabled) {
866					auto &db_instance = DatabaseInstance::GetDatabase(*this);
867					ValidChecker::Invalidate(db_instance, error.RawMessage());
868				}
869			}
870			// other types of exceptions do invalidate the current transaction
871			pending = ErrorResult<PendingQueryResult>(std::move(error), query);
872		}
873		if (pending->HasError()) {
874			// query failed: abort now
875			EndQueryInternal(lock, false, invalidate_query, pending->GetErrorObject());
876			return pending;
877		}
878		D_ASSERT(active_query->IsOpenResult(*pending));
879		return pending;
880	}
