884	#ifdef DUCKDB_FORCE_QUERY_LOG
885			try {
886				string log_path(DUCKDB_FORCE_QUERY_LOG);
887				client_data->log_query_writer =
888				    make_uniq<BufferedFileWriter>(FileSystem::GetFileSystem(*this), log_path,
889				                                  BufferedFileWriter::DEFAULT_OPEN_FLAGS, client_data->file_opener.get());
890			} catch (...) {
891				return;
892			}
893	#else
894			return;
